import os
import queue
import threading
from collections.abc import Iterator

import pyaudio
from google.cloud import speech_v1 as speech


class StreamingSpeechToText:
    def __init__(
        self,
        language_code: str = "en-US",
        rate: int = 16000,
        chunk_ms: int = 100,
    ) -> None:
        self.language_code = language_code
        self.rate = rate
        self.chunk_size = int(rate * chunk_ms / 1000)
        self._audio_interface = pyaudio.PyAudio()
        self._audio_stream = None
        self._buffer: queue.Queue[bytes | None] = queue.Queue()
        self._closed = True

    def __enter__(self) -> "StreamingSpeechToText":
        self._closed = False
        self._audio_stream = self._audio_interface.open(
            format=pyaudio.paInt16,
            channels=1,
            rate=self.rate,
            input=True,
            frames_per_buffer=self.chunk_size,
            stream_callback=self._fill_buffer,
        )
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self._closed = True
        if self._audio_stream is not None:
            self._audio_stream.stop_stream()
            self._audio_stream.close()
        self._buffer.put(None)
        self._audio_interface.terminate()

    def _fill_buffer(self, in_data, frame_count, time_info, status_flags):
        self._buffer.put(in_data)
        return None, pyaudio.paContinue

    def _audio_generator(self) -> Iterator[bytes]:
        while not self._closed:
            chunk = self._buffer.get()
            if chunk is None:
                return

            data = [chunk]
            while True:
                try:
                    chunk = self._buffer.get_nowait()
                except queue.Empty:
                    break
                if chunk is None:
                    return
                data.append(chunk)

            yield b"".join(data)

    def transcripts(self) -> Iterator[dict]:
        client = speech.SpeechClient()

        recognition_config = speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=self.rate,
            language_code=self.language_code,
            model="latest_long",
            enable_automatic_punctuation=True,
        )

        streaming_config = speech.StreamingRecognitionConfig(
            config=recognition_config,
            interim_results=True,
            single_utterance=False,
        )

        requests = (
            speech.StreamingRecognizeRequest(audio_content=content)
            for content in self._audio_generator()
        )

        responses = client.streaming_recognize(
            config=streaming_config,
            requests=requests,
        )

        for response in responses:
            for result in response.results:
                if not result.alternatives:
                    continue
                alt = result.alternatives[0]
                yield {
                    "transcript": alt.transcript,
                    "is_final": result.is_final,
                    "stability": getattr(result, "stability", 0.0),
                    "confidence": getattr(alt, "confidence", 0.0),
                }


def stream_microphone_transcripts() -> Iterator[dict]:
    if not os.getenv("GOOGLE_APPLICATION_CREDENTIALS"):
        raise EnvironmentError(
            "Set GOOGLE_APPLICATION_CREDENTIALS to a Google Cloud service account JSON file."
        )

    with StreamingSpeechToText() as stt:
        yield from stt.transcripts()
